132→// AssertCheckpointAdvanced asserts the checkpoint branch moved forward.
133→func AssertCheckpointAdvanced(t *testing.T, s *RepoState) {
134→	t.Helper()
135→	after := GitOutput(t, s.Dir, "rev-parse", "entire/checkpoints/v1")
136→	assert.NotEqual(t, s.CheckpointBefore, after, "checkpoint branch did not advance")
137→}
