139→// AssertCheckpointNotAdvanced asserts the checkpoint branch has NOT moved.
140→func AssertCheckpointNotAdvanced(t *testing.T, s *RepoState) {
141→	t.Helper()
142→	after := GitOutput(t, s.Dir, "rev-parse", "entire/checkpoints/v1")
143→	assert.Equal(t, s.CheckpointBefore, after, "checkpoint branch advanced unexpectedly")
144→}
