146→// AssertCheckpointIDFormat asserts the checkpoint ID is 12 lowercase hex chars.
147→func AssertCheckpointIDFormat(t *testing.T, checkpointID string) {
148→	t.Helper()
149→	assert.Regexp(t, hexIDPattern, checkpointID,
150→		"checkpoint ID %q should be 12 lowercase hex chars", checkpointID)
