153→// AssertHasCheckpointTrailer asserts the commit has an Entire-Checkpoint trailer,
154→// validates its format, and returns its value.
155→func AssertHasCheckpointTrailer(t *testing.T, dir string, ref string) string {
156→	t.Helper()
157→	trailer := GetCheckpointTrailer(t, dir, ref)
158→	require.NotEmpty(t, trailer, "no Entire-Checkpoint trailer on %s", ref)
159→	AssertCheckpointIDFormat(t, trailer)
160→	return trailer
161→}
