163→// AssertCheckpointInLastN asserts the given checkpoint ID appears in at
164→// least n commits on the checkpoint branch (e.g. initial + catchup).
165→// Uses --grep to find matching commits regardless of position, so extra
166→// commits from multi-commit agent turns don't cause false failures.
167→func AssertCheckpointInLastN(t *testing.T, dir string, checkpointID string, n int) {
168→	t.Helper()
169→	out := GitOutput(t, dir, "log", "--grep="+checkpointID,
170→		"--format=%s", "entire/checkpoints/v1")
171→	var lines []string
172→	for _, line := range strings.Split(strings.TrimSpace(out), "\n") {
173→		if line != "" {
174→			lines = append(lines, line)
175→		}
176→	}
177→	assert.GreaterOrEqual(t, len(lines), n,
178→		"expected at least %d commits mentioning %s on checkpoint branch, got %d: %v",
179→		n, checkpointID, len(lines), lines)
180→}
