182→// AssertCheckpointExists asserts that the checkpoint ID is mentioned on
183→// the checkpoint branch and that its metadata.json exists in the tree.
184→func AssertCheckpointExists(t *testing.T, dir string, checkpointID string) {
185→	t.Helper()
186→	out := GitOutput(t, dir, "log", "entire/checkpoints/v1", "--grep="+checkpointID, "--oneline")
187→	assert.NotEmpty(t, out, "checkpoint %s not found on checkpoint branch", checkpointID)
188→
189→	path := CheckpointPath(checkpointID) + "/metadata.json"
190→	blob := "entire/checkpoints/v1:" + path
191→	raw := gitOutputSafe(dir, "show", blob)
192→	assert.NotEmpty(t, raw,
193→		"checkpoint %s metadata not found at %s", checkpointID, path)
194→}
